"""L2-09: rigorous e-descent for C3_p : y^2 = F1(T,W) F2(T,W)   (Python 3 + cypari2, PARI/GP 2.17)
F1 = q_p q_{1/p},  F2 = q_c q_{1/c}  (integral binary quartic forms), p = a/b, c = (a+b)/(a-b).
For a rational point with F1F2 != 0, the squarefree class e of F1(T,W) (= class of F2) lies in
  Sel_e = { e > 0 squarefree, supp(e) in S', e in Img_l for all l in S' }
where Img_l ⊇ { class of F1(t) : t in P^1(Q_l), F1(t)F2(t) in Q_l*^2 }  (superset-safe disc refinement below).
If Sel_e = {1} and Jac(y^2 = F_i(x,1)) has rank 0 (proved upper bound) and |E(Q)| = 8 (= number of known
points t = 0, inf, 1, -1 on y^2 = F_i), then every rational point of C3_p has t in {0, inf, 1, -1}.
Usage:  python3 L2-09_edesc.py a b
"""
import cypari2, sys
pari = cypari2.Pari(); pari.allocatemem(2**31, silent=True)

def forms(a, b):
    q = {'p': (b*b, a*a), '1/p': (a*a, b*b), 'c': ((a-b)**2, (a+b)**2), '1/c': ((a+b)**2, (a-b)**2)}
    return q

def evalq(AB, T, W): return AB[0]*T*T + AB[1]*W*W

def F1F2(a, b, T, W):
    q = forms(a, b)
    return evalq(q['p'], T, W)*evalq(q['1/p'], T, W), evalq(q['c'], T, W)*evalq(q['1/c'], T, W)

def val(n, l):
    if n == 0: return 10**9
    k = 0
    while n % l == 0: n //= l; k += 1
    return k

def unit(n, l):
    while n % l == 0: n //= l
    return n

def cls(n, l):
    """class in Q_l*/Q_l*^2 of nonzero integer n"""
    k = val(n, l); u = unit(n, l)
    if l == 2: return (k % 2, u % 8)
    return (k % 2, int(pari.kronecker(u % l, l)))

def is_sq_class(c, l):
    return c[0] == 0 and (c[1] == 1)

def mul_cls(c1, c2, l):
    if l == 2: return ((c1[0]+c2[0]) % 2, (c1[1]*c2[1]) % 8)
    return ((c1[0]+c2[0]) % 2, c1[1]*c2[1])

def local_image(a, b, l, kmax=40):
    """superset of the image of {t in P^1(Q_l): F1F2 square} -> class of F1, by disc refinement.
    chart 0: (T:1), T in Z_l ; chart 1: (1:W), W in l Z_l.
    On a disc z = c0 mod l^k, F(z) = F(c0) mod l^k (integer coefficients), so if v(F(c0)) <= k-1 (k-3 for l=2)
    the class of F is constant on the disc."""
    need = 3 if l == 2 else 1
    img = set()
    unresolved = []
    stack = [(0, r, 1) for r in range(l)] + [(1, 0, 1)]
    while stack:
        ch, c0, k = stack.pop()
        T, W = (c0, 1) if ch == 0 else (1, c0)
        f1, f2 = F1F2(a, b, T, W)
        v1, v2 = val(f1, l), val(f2, l)
        if v1 <= k - need and v2 <= k - need:
            # both classes constant on the disc (exact)
            c1, c2 = cls(f1, l), cls(f2, l)
            if is_sq_class(mul_cls(c1, c2, l), l):
                img.add(c1)
            continue
        if v2 <= k - need:
            # F2 class constant on the disc; the square condition forces class(F1) = class(F2): superset-safe
            img.add(cls(f2, l)); continue
        if v1 <= k - need:
            img.add(cls(f1, l)); continue
        if k >= kmax:
            unresolved.append((ch, c0, k, v1, v2)); continue
        for r in range(l):
            stack.append((ch, c0 + r*l**k, k+1))
    return img, unresolved

def S_prime(a, b):
    """2 and the primes dividing the resultants (A_i D_j - B_i C_j) of the four quadratic forms"""
    q = forms(a, b); ks = list(q); S = {2}
    for i in range(4):
        for j in range(i+1, 4):
            A, B = q[ks[i]]; C, D = q[ks[j]]
            n = abs(A*D - B*C)
            if n > 1: S |= set(int(x) for x in pari.factor(n)[0])
    return sorted(S)

def sel_e(a, b, kmax=40):
    S = S_prime(a, b)
    imgs = {}; problems = []
    for l in S:
        img, unres = local_image(a, b, l, kmax)
        imgs[l] = img
        if unres: problems.append((l, len(unres)))
    sel = []
    from itertools import combinations
    for r in range(len(S)+1):
        for sub in combinations(S, r):
            e = 1
            for x in sub: e *= x
            if all(cls(e, l) in imgs[l] for l in S): sel.append(e)
    return S, imgs, sel, problems

def jac_check(a, b, which):
    """y^2 = F_which(x,1); returns (rank bounds from ellrank, |E(Q)_tors|) of its Jacobian"""
    q = forms(a, b)
    if which == 1: A, B = q['p'], q['1/p']
    else: A, B = q['c'], q['1/c']
    pol = pari(f'({A[0]}*x^2+{A[1]})*({B[0]}*x^2+{B[1]})')
    E = pari.ellinit(pari.ellfromeqn(pari('y^2') - pol))
    r = pari.ellrank(E)
    return (int(r[0]), int(r[1])), int(pari.elltors(E)[0])

def decide(a, b, kmax=40):
    S, imgs, sel, problems = sel_e(a, b, kmax)
    res = {'p': f'{a}/{b}', 'S': S, 'sel': sel, 'problems': problems}
    if problems or sel != [1]:
        res['verdict'] = 'OPEN (Sel_e != {1} or unresolved discs)'
        return res
    for which in (2, 1):
        rk, nt = jac_check(a, b, which)
        res[f'J{which}'] = (rk, nt)
        if rk == (0, 0) and nt == 8:
            res['verdict'] = f'EXCLUDED via F{which}: only t in {{0,inf,1,-1}}'
            return res
    res['verdict'] = 'OPEN (no rank-0 factor)'
    return res

if __name__ == '__main__':
    a, b = int(sys.argv[1]), int(sys.argv[2])
    print(decide(a, b))

# Expected (PARI/GP 2.17.2):
# 10 1 -> sel [1], J2 ((0,0),8), EXCLUDED via F2
# 23 1 -> sel [1], J2 ((0,0),8), EXCLUDED via F2
# 11 6 -> sel [1], J2 ((1,1),8), J1 ((0,0),8), EXCLUDED via F1
